from pathlib import Path
import json,hashlib
root=Path('/tmp/engine-cost-map-20261104')
data=(root/'source/scripts/lib/native_motion/engine.wasm').read_bytes()
class Reader:
 def __init__(self,b):self.b=b;self.i=0
 def byte(self):v=self.b[self.i];self.i+=1;return v
 def integer(self):
  v=s=0
  while True:
   c=self.byte();v|=(c&127)<<s
   if c<128:return v
   s+=7
 def take(self,n):v=self.b[self.i:self.i+n];self.i+=n;return v
 def string(self):return self.take(self.integer()).decode()
r=Reader(data);assert r.take(8)==b'\x00asm\x01\x00\x00\x00';exports={}
while r.i<len(data):
 k=r.byte();section=Reader(r.take(r.integer()))
 if k==7:
  for _ in range(section.integer()):
   name=section.string();kind=section.byte();index=section.integer()
   if kind==0:exports[index]=name
(root/'wasm-exports.json').write_text(json.dumps({'sha256':hashlib.sha256(data).hexdigest(),'functionExports':exports},indent=2)+'\n')
print(exports)

